import{_ as a,c as r,o as t,aM as o}from"./chunks/framework.kKeYZnSg.js";const l="/fe-handbook/assets/3731b52da72d5fc2b2930e7655b84688.D4Xdo8bK.png",i="/fe-handbook/assets/4bf5826b53c08cb1215802bfdc141b0c.CZK2A5Rm.png",g=JSON.parse('{"title":"SSG (Static Site Generator)","description":"","frontmatter":{},"headers":[],"relativePath":"advance/ssg/index.md","filePath":"advance/ssg/index.md","lastUpdated":1785684385000}'),n={name:"advance/ssg/index.md"};function s(h,e,c,d,p,f){return t(),r("div",null,e[0]||(e[0]=[o('<h1 id="ssg-static-site-generator" tabindex="-1">SSG (Static Site Generator) <a class="header-anchor" href="#ssg-static-site-generator" aria-label="Permalink to &quot;SSG (Static Site Generator)&quot;">​</a></h1><blockquote><p>SSG 是 &quot;Static Site Generation&quot;（静态网站生成）的缩写。它表示网页在<strong>构建阶段</strong>被预先渲染成静态的 HTML，然后直接提供给客户端，而不需要服务器实时生成 HTML。</p><p>在传统的 SSR 中，每当用户请求一个页面时，服务器就会实时生成 HTML。有了 SSG，HTML 可以在构建过程中被提前生成，并被托管在 CDN 或其他静态资源服务中。</p><p>与传统的 SSR 相比，SSG 可以提供更快的加载速度以及更少的服务端开销，因为不需要维护一个服务器来实时生成 HTML。然而，SSG 不适合需要动态内容的网站，因为 HTML 是在构建过程中生成的，不支持实时更新。</p></blockquote><h2 id="ssg-的优势" tabindex="-1">SSG 的优势 <a class="header-anchor" href="#ssg-的优势" aria-label="Permalink to &quot;SSG 的优势&quot;">​</a></h2><ul><li>首屏渲染更快：用户无需等待 JavaScript 加载和执行，浏览器加载 HTML 后即可看到完整内容，而不是在用户访问时才进行渲染。</li><li>SEO 友好：搜索引擎爬虫可以直接抓取到完整的 HTML 内容。</li><li>易于部署：产物是纯静态文件，无需部署服务器 API，可直接上传到 CDN 或任何静态托管服务。</li></ul><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><h3 id="image-hosting-service" tabindex="-1">Image hosting service <a class="header-anchor" href="#image-hosting-service" aria-label="Permalink to &quot;Image hosting service&quot;">​</a></h3><ul><li><a href="https://imgkr.com/" target="_blank" rel="nofollow noopener noreferrer">图壳</a></li><li>GitHub + jsdelivr + PicGo</li><li>各大云服务对象存储cos</li></ul><h3 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h3><ul><li><a href="https://disqus.com/" target="_blank" rel="nofollow noopener noreferrer">disqus</a></li></ul><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><ul><li><a href="https://www.algolia.com/" target="_blank" rel="nofollow noopener noreferrer">algolia</a> 非常好用</li><li><a href="https://typesense.org/" target="_blank" rel="nofollow noopener noreferrer">typesense</a></li></ul><h3 id="badge" tabindex="-1">Badge <a class="header-anchor" href="#badge" aria-label="Permalink to &quot;Badge&quot;">​</a></h3><ul><li><a href="https://shields.io/" target="_blank" rel="nofollow noopener noreferrer">bandage</a> 一般用于开源项目，统计 star, fork, issues, pull request, release, deploy, visitors</li></ul><p><img src="'+l+'" alt="在这里插入图片描述"></p><p><img src="'+i+'" alt="在这里插入图片描述"></p><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h3><ul><li><a href="https://marketingplatform.google.com/about/analytics/" target="_blank" rel="nofollow noopener noreferrer">Google Analytics</a></li></ul><h3 id="code-image" tabindex="-1">Code Image <a class="header-anchor" href="#code-image" aria-label="Permalink to &quot;Code Image&quot;">​</a></h3><ul><li><p><a href="https://www.codepng.app/" target="_blank" rel="nofollow noopener noreferrer">https://www.codepng.app/</a></p></li><li><p><a href="https://carbon.now.sh/" target="_blank" rel="nofollow noopener noreferrer">https://carbon.now.sh/</a></p></li><li><p><a href="https://live2d.fghrsh.net/demo/1.4.2/waifu-tips.html" target="_blank" rel="nofollow noopener noreferrer">https://live2d.fghrsh.net/demo/1.4.2/waifu-tips.html</a>)</p></li></ul><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><h3 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-label="Permalink to &quot;GitHub Pages&quot;">​</a></h3><h3 id="gitlab-pages" tabindex="-1">GitLab Pages <a class="header-anchor" href="#gitlab-pages" aria-label="Permalink to &quot;GitLab Pages&quot;">​</a></h3><h3 id="cloudflare-pages" tabindex="-1">Cloudflare Pages <a class="header-anchor" href="#cloudflare-pages" aria-label="Permalink to &quot;Cloudflare Pages&quot;">​</a></h3><h3 id="vercel" tabindex="-1"><a href="https://vercel.com/" target="_blank" rel="nofollow noopener noreferrer">Vercel</a> <a class="header-anchor" href="#vercel" aria-label="Permalink to &quot;[Vercel](https://vercel.com/)&quot;">​</a></h3><h3 id="netlify" tabindex="-1"><a href="https://www.netlify.com/" target="_blank" rel="nofollow noopener noreferrer">Netlify</a> <a class="header-anchor" href="#netlify" aria-label="Permalink to &quot;[Netlify](https://www.netlify.com/)&quot;">​</a></h3>',25)]))}const b=a(n,[["render",s]]);export{g as __pageData,b as default};
